-- ==========================================================================
-- B4 FOLLOW-ON FIX (decision): decision: duplicate question rewritten into a new question
--
-- Courses: decision. Rows changed: 1; rows inserted: 0.
-- Source: tools/answer-length-audit/fixes/decision.json (every item, its verdict and
-- its reason, old and new text side by side); generated by
-- tools/answer-length-audit/fix.py sql decision. Runs AFTER the 29 B4 length files
-- and any earlier fix file: every guard below is the text those leave behind.
--
-- GUARDS. Each changed row must match its OLD prompt, explanation and options
-- (md5) and answer_index exactly (then it is updated) or its NEW ones (already
-- applied, left alone). Anything else raises and the transaction rolls back.
-- Each insert must be absent (inserted) or present with the same text (left).
-- Each course ends at its asserted question count. SAFE TO RE-RUN.
-- ==========================================================================

do $$
declare
  v_state   text;
  v_count   integer;
  v_updated integer := 0;
  v_total   integer;
begin

  -- decision advanced module m06-the-expert-reading ord 10
  select case when md5(prompt) = '1e18a347ff41451d38f1356f37fbf8cf' and md5(coalesce(explanation, '')) = 'b753f674799f2c5efb2a8f288e9435c4' and md5(options::text) = md5('["Nothing to the value, because a likelihood and a posterior are the same number whenever the survey passes its consistency check.", "It values the drill at 207.7989 regardless, because the engine converts any typed 0.850000 into the posterior before weighting the drill.", "It values the drill at 298.2500 in place of 207.7989, because the posterior after a bright spot is 0.646739.", "It lowers the drill after a bright spot to 9.2361, since that likelihood belongs to the reading on which the farm-out is chosen."]'::jsonb::text) and answer_index = 2 then 'old'
              when md5(prompt) = '8d49c8630ee8ca276242076a4828cebf' and md5(coalesce(explanation, '')) = '94a5f2fb7373a79fef5d5fdfab40faa2' and md5(options::text) = md5('["Because each project''s EMV has to be turned into a net value of information before projects on different prospects can be compared at all.", "Because a portfolio rolls every project back at the discount rate of its riskiest member, which lowers each value unevenly and so reorders them.", "Because money spent on one project is unavailable to the next, so each is judged against what else the same budget buys.", "Because an individually best project was valued with its own information already bought, and a portfolio has to strip every survey value out first."]'::jsonb::text) and answer_index = 2 then 'new'
              else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'decision' and tier = 'advanced' and scope = 'module' and module_key is not distinct from 'm06-the-expert-reading' and ord = 10 and active;
  if v_state is null then raise exception 'B4 fix decision refused: no row for decision advanced module m06-the-expert-reading ord 10'; end if;
  if v_state = 'other' then raise exception 'B4 fix decision refused: decision advanced module m06-the-expert-reading ord 10 matches neither its current nor its fixed form'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions set prompt = 'The onward lesson takes decision analysis on to capital portfolio decisions under one budget. Why is the best set of projects not simply the set of individually best ones?', options = '["Because each project''s EMV has to be turned into a net value of information before projects on different prospects can be compared at all.", "Because a portfolio rolls every project back at the discount rate of its riskiest member, which lowers each value unevenly and so reorders them.", "Because money spent on one project is unavailable to the next, so each is judged against what else the same budget buys.", "Because an individually best project was valued with its own information already bought, and a portfolio has to strip every survey value out first."]'::jsonb,
           answer_index = 2, explanation = 'Capital portfolio decisions choose among many projects under one budget, and money spent on one is unavailable to the next, so the choice is of a set under that constraint. Decision Studio already sets capital allocation from a saved portfolio beside the decision analysis in one brief.'
     where app_slug = 'decision' and tier = 'advanced' and scope = 'module' and module_key is not distinct from 'm06-the-expert-reading' and ord = 10 and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'B4 fix decision refused: decision advanced module m06-the-expert-reading ord 10 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  select count(*) into v_total from public.academy_quiz_questions where app_slug = 'decision' and active;
  if v_total <> 396 then raise exception 'B4 fix decision refused: decision holds % active questions, expected 396', v_total; end if;
  raise notice 'B4 fix decision: % of 1 rows written, the rest already carried the fixed text', v_updated;
end $$;
